(()=>{const fd=document.getElementById('frontDesk');const field=fd.closest('.field');field.innerHTML='<label>Phân công operational</label><div class="op-box"><label class="op-check"><input type="checkbox" id="frontDesk"> Front Desk</label><label class="op-check"><input type="checkbox" id="shiftLeader"> Shift Leader</label><label class="op-check"><input type="checkbox" id="teacherRole"> Teacher</label><div id="teacherClasses" class="class-picker" hidden></div><label class="op-check"><input type="checkbox" id="taRole"> Teaching Assistant (TA)</label><div id="taClasses" class="class-picker" hidden></div><p class="hint">Teacher/TA gắn RunningClass. Front Desk gắn ca và trung tâm.</p></div>';const session=document.getElementById('sessionList');session.textContent='Chọn Teacher hoặc TA để phân công RunningClass.';const classes=[{id:'RC-ART-01',name:'Mỹ thuật · Lớp A',time:'18:00–19:30',days:[0,2,4]},{id:'RC-PIANO-02',name:'Piano · Lớp B',time:'19:30–21:00',days:[1,3,5]},{id:'RC-ART-03',name:'Mỹ thuật · Lớp C',time:'18:00–19:30',days:[1,3,6]},{id:'RC-PIANO-04',name:'Piano · Lớp D',time:'18:00–19:30',days:[0,2,4]}];const state={};const $=id=>document.getElementById(id);const key=()=>selected.join('-')+'@'+weekOffset;function eligible(){return classes.filter(c=>c.days.includes(selected[1]))}function pick(role){const box=$(role+'Classes'),checked=$(role==='teacher'?'teacherRole':'taRole').checked;box.hidden=!checked;box.innerHTML=eligible().map(c=>'<label class="class-option"><input type="checkbox" value="'+c.id+'"> <span>'+c.name+'<small>'+c.time+' · '+c.id+'</small></span></label>').join('')||'<p class="hint">Không có RunningClass phù hợp ngày này.</p>'}function refresh(){pick('teacher');pick('ta');const saved=state[key()];if(saved){$('frontDesk').checked=saved.fd;$('shiftLeader').checked=!!saved.leader;$('teacherRole').checked=saved.teacher.length>0;$('taRole').checked=saved.ta.length>0;pick('teacher');pick('ta');['teacher','ta'].forEach(role=>$(role+'Classes').querySelectorAll('input').forEach(el=>el.checked=saved[role].includes(el.value)))}else{$('frontDesk').checked=false;$('shiftLeader').checked=false;$('teacherRole').checked=false;$('taRole').checked=false;pick('teacher');pick('ta')}session.textContent=eligible().length?'RunningClass khả dụng: '+eligible().map(c=>c.name).join(', '):'Không có RunningClass phù hợp ngày này.'}['teacher','ta'].forEach(role=>$(role==='teacher'?'teacherRole':'taRole').addEventListener('change',()=>pick(role)));const oldChoose=choose;choose=function(i,j){oldChoose(i,j);refresh()};const oldSave=save;save=function(){const teacher=$('teacherRole').checked?[...$('teacherClasses').querySelectorAll('input:checked')].map(x=>x.value):[];const ta=$('taRole').checked?[...$('taClasses').querySelectorAll('input:checked')].map(x=>x.value):[];if($('teacherRole').checked&&!teacher.length)return toast('Teacher cần chọn ít nhất một RunningClass');if($('taRole').checked&&!ta.length)return toast('TA cần chọn ít nhất một RunningClass');if(!$('frontDesk').checked&&!$('shiftLeader').checked&&!teacher.length&&!ta.length)return toast('Chọn ít nhất một vai trò');if(teacher.some(id=>ta.includes(id)))return toast('Một người không thể vừa Teacher vừa TA cùng RunningClass');state[key()]={fd:$('frontDesk').checked,leader:$('shiftLeader').checked,teacher,ta};oldSave();};refresh()})();